class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        n, m = len(haystack), len(needle)

        if n < m:
            return -1

        hayHash = 0
        needleHash = 0
        for i in range(len(needle)):
            hayHash += ord(haystack[i])
            needleHash += ord(needle[i])

        for i in range(n - m + 1):
            if hayHash == needleHash and needle == haystack[i:i+m]:
                return i

            if i < n - m:
                hayHash = hayHash - ord(haystack[i]) + ord(haystack[i + m])

        return -1
